,p_created_on=>wwv_flow_imp.dz('20260831101239Z')
,p_updated_on=>wwv_flow_imp.dz('20260901054209Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(28667885144079215249)
,p_name=>'Key Data Ingestion Behaviors'
,p_static_id=>'key-data-ingestion-behaviors'
,p_template=>4073835273271169698
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#::::::t-Region--scrollBody::::::::::'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--horizontalBorders:'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'    ''<b>'' || Insert_Behavior || ''</b>'' as Insert_Behavior,',
'    Operational_Action,',
'    Handling_of_Matches,',
'    seq',
'from(',
'    SELECT ',
'        ''Append'' as Insert_Behavior,',
'        ''Insert all rows.'' as Operational_Action,',
'        ''Skips or ignores rows matching an established primary key'' as Handling_of_Matches,',
'        1 as seq',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Merge'',',
'        ''Inserts new entries.'',',
'        ''Updates existing entries contining a matching primary key.'',',
'        2',
'    FROM DUAL',
'    UNION ALL',
'    SELECT ',
'        ''Replace'',',
'        ''Replaces all table data.'',',
'        ''Completely deletes existing records before adding new file data.'',',
'        3',
'    FROM DUAL',
')',
'order by seq'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_created_on=>wwv_flow_imp.dz('20260901071832Z')
,p_updated_on=>wwv_flow_imp.dz('20260901094216Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
