wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(32987802606554587021)
,p_name=>'Preview'
,p_static_id=>'preview'
,p_template=>4073835273271169698
,p_display_sequence=>40
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--inline:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- select p.line_number,',
'--        p.col001, p.col002, p.col003, p.col004, p.col005, p.col006, p.col007, p.col008, p.col009, p.col010',
'--        -- add more columns (col011 to col300) here.',
'--   from apex_application_temp_files f, ',
'--        table( apex_data_parser.parse(',
'--                   p_content           => f.blob_content,',
'--                   p_file_name         => f.filename,',
'--                   p_xlsx_sheet_name   => case when :P2_XLSX_WORKSHEET is not null then :P2_XLSX_WORKSHEET end,',
'--                   p_file_profile      => apex_data_loading.get_file_profile( p_static_id => ''data-load-definition'' ),',
'--                   p_max_rows          => 100 ) ) p',
'--  where f.name = :P2_FILE',
'',
'SELECT',
'       (p.line_number - 1) AS SEQ,',
'       INITCAP(TRIM(p.col001)) AS EMPLOYEE_NAME,',
'       UPPER(TRIM(p.col002)) AS DEPARTMENT,',
'       LOWER(TRIM(p.col003)) AS EMAIL,',
'       TO_DATE(TRIM(p.col004), ''YYYY-MM-DD'') AS JOINING_DATE,',
'       TO_DATE(TRIM(p.col005), ''YYYY-MM-DD'') AS DATE_OF_BIRTH,',
'       TO_NUMBER(TRIM(p.col006), ''999999999999D99'') AS SALARY,',
'       TO_NUMBER(TRIM(p.col007), ''999999999999D99'') AS BONUS,',
'       TO_NUMBER(TRIM(p.col008), ''999D99'') AS EXPERIENCE_YRS,',
'       UPPER(TRIM(p.col009)) AS STATUS',
'FROM apex_application_temp_files f,',
'     TABLE(',
'         apex_data_parser.parse(',
'             p_content         => f.blob_content,',
'             p_file_name       => f.filename,',
'             p_xlsx_sheet_name =>',
'                 CASE',
'                     WHEN :P2_XLSX_WORKSHEET IS NOT NULL',
'                     THEN :P2_XLSX_WORKSHEET',
'                 END,',
'             p_file_profile    =>',
'                 apex_data_loading.get_file_profile(',
'                     p_static_id => ''employee-data''',
'                 ),',
'             p_max_rows        => 100',
'         )',
'     ) p',
'',
'WHERE f.name = :P2_FILE',
'  AND p.line_number <> 1;'))
,p_display_when_condition=>'P2_FILE'
,p_display_condition_type=>'ITEM_IS_NOT_NULL'
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'No data found.'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_created_on=>wwv_flow_imp.dz('20260831103004Z')
,p_updated_on=>wwv_flow_imp.dz('20260907093030Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
