wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(28667884393566215241)
,p_process_sequence=>20
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Validate and Load TA_USER'
,p_static_id=>'validate-and-load-ta-user'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob        BLOB;',
'    l_error_count NUMBER := 0;',
'    l_error_msg   VARCHAR2(32767);',
'    l_result      apex_data_loading.t_data_load_result;',
'BEGIN',
'    /* =========================================================',
'       1. GET UPLOADED FILE',
'       ========================================================= */',
'    SELECT blob_content',
'      INTO l_blob',
'      FROM apex_application_temp_files',
'     WHERE name = :P2_FILE;',
'    /* =========================================================',
'       2. VALIDATE DATA ROWS',
'          IMPORTANT:',
'          line_number = 1 is the Excel header.',
'          We explicitly ignore it.',
'       ========================================================= */',
'    SELECT COUNT(*)',
'      INTO l_error_count',
'      FROM',
'      (',
'          SELECT',
'              p.line_number,',
'              TRIM(p.col001) AS username,',
'              TRIM(p.col002) AS password,',
'              COUNT(*) OVER',
'              (',
'                  PARTITION BY UPPER(TRIM(p.col001))',
'              ) AS username_count',
'          FROM TABLE',
'          (',
'              apex_data_parser.parse',
'              (',
'                  p_content =>',
'                      l_blob,',
'                  p_file_name =>',
'                      :P2_FILE,',
'                  p_xlsx_sheet_name =>',
'                      CASE',
'                          WHEN :P2_XLSX_WORKSHEET IS NOT NULL',
'                          THEN :P2_XLSX_WORKSHEET',
'                      END,',
'',
'                  p_file_profile =>',
'                      apex_data_loading.get_file_profile',
'                      (',
'                          p_static_id =>',
'                              ''data-load-definition''',
'                      ),',
'',
'                  p_max_rows => 100000',
'              )',
'          ) p',
'          /* ================================================',
'             IGNORE EXCEL HEADER ROW',
'             ================================================ */',
'          WHERE p.line_number > 1',
'      ) d',
'     WHERE',
'           /* =================================================',
'              USERNAME VALIDATION',
'              ================================================= */',
'           d.username IS NULL',
'        OR LENGTH(d.username) > 255',
'        OR NOT REGEXP_LIKE',
'           (',
'               d.username,',
'               ''^[A-Za-z0-9._-]+$''',
'           )',
'        OR d.username_count > 1',
'        OR EXISTS',
'           (',
'               SELECT 1',
'                 FROM TA_USER t',
'                WHERE UPPER(TRIM(t.USERNAME)) =',
'                      UPPER(TRIM(d.username))',
'           )',
'           /* =================================================',
'              PASSWORD VALIDATION',
'              ================================================= */',
'        OR d.password IS NULL',
'        OR LENGTH(d.password) < 8',
'        OR LENGTH(d.password) > 255',
'        OR NOT REGEXP_LIKE',
'           (',
'               d.password,',
'               ''[A-Z]''',
'           )',
'        OR NOT REGEXP_LIKE',
'           (',
'               d.password,',
'               ''[a-z]''',
'           )',
'        OR NOT REGEXP_LIKE',
'           (',
'               d.password,',
'               ''[0-9]''',
'           )',
'        OR NOT REGEXP_LIKE',
'           (',
'               d.password,',
'               ''[^A-Za-z0-9]''',
'           );',
'    /* =========================================================',
'       3. STOP LOAD IF ANY VALIDATION ERROR EXISTS',
'       ========================================================= */',
'    IF l_error_count > 0 THEN',
'        raise_application_error',
'        (',
'            -20001,',
'            ''Data validation failed. '' ||',
'            l_error_count ||',
'            '' invalid row(s) found. '' ||',
'            ''Please correct the Excel file and upload it again.''',
'        );',
'    END IF;',
'    /* ========================================================',
unistr('       4. ALL DATA VALID \2192 LOAD DATA'),
'       ========================================================= */',
'    l_result :=',
'        apex_data_loading.load_data',
'        (',
'            p_application_id =>',
'                :APP_ID,',
'            p_static_id =>',
'                ''data-load-definition'',',
'            p_data_to_load =>',
'                l_blob,',
'            p_xlsx_sheet_name =>',
'                CASE',
'                    WHEN :P2_XLSX_WORKSHEET IS NOT NULL',
'                    THEN :P2_XLSX_WORKSHEET',
'                END',
'        );',
'    /* =========================================================',
'       5. CHECK APEX LOAD RESULT',
'       ========================================================= */',
'    IF l_result.error_rows > 0 THEN',
'        raise_application_error',
'        (',
'            -20002,',
'            ''Data loading completed with '' ||',
'            l_result.error_rows ||',
'            '' error row(s). '' ||',
'            l_result.processed_rows ||',
'            '' row(s) processed.''',
'        );',
'    END IF;',
'    /* =========================================================',
'       6. SUCCESS MESSAGE',
'       ========================================================= */',
'    apex_application.g_print_success_message :=',
'        l_result.processed_rows ||',
'        '' row(s) loaded successfully.'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(32987796058804587013)
,p_process_when_type=>'NEVER'
,p_internal_uid=>28667884393566215241
,p_created_on=>wwv_flow_imp.dz('20260831122836Z')
,p_updated_on=>wwv_flow_imp.dz('20260907133249Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
end;
