,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'       (p.line_number - 1) AS SEQ,',
'       INITCAP(TRIM(p.col001)) AS EMPLOYEE_NAME,',
'       UPPER(TRIM(p.col002)) AS DEPARTMENT,',
'       LOWER(TRIM(p.col003)) AS EMAIL,',
'       TO_DATE(TRIM(p.col004), ''YYYY-MM-DD'') AS JOINING_DATE,',
'       TO_DATE(TRIM(p.col005), ''YYYY-MM-DD'') AS DATE_OF_BIRTH,',
'       TO_NUMBER(TRIM(p.col006), ''999999999999D99'') AS SALARY,',
'       TO_NUMBER(TRIM(p.col007), ''999999999999D99'') AS BONUS,',
'       TO_NUMBER(TRIM(p.col008), ''999D99'') AS EXPERIENCE_YRS,',
'       UPPER(TRIM(p.col009)) AS STATUS',
'FROM apex_application_temp_files f,',
'     TABLE(',
'         apex_data_parser.parse(',
'             p_content         => f.blob_content,',
'             p_file_name       => f.filename,',
'             p_xlsx_sheet_name =>',
'                 CASE',
'                     WHEN :P3_XLSX_WORKSHEET IS NOT NULL',
'                     THEN :P3_XLSX_WORKSHEET',
'                 END,',
'             p_file_profile    =>',
'                 apex_data_loading.get_file_profile(',
'                     p_static_id => ''employee-data''',
'                 ),',
'             p_max_rows        => 100',
'         )',
'     ) p',
'',
'WHERE f.name = :P3_FILE',
'  AND p.line_number <> 1;'))
,p_display_when_condition=>'P3_FILE'
,p_display_condition_type=>'ITEM_IS_NOT_NULL'
