wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(33219523615752145532)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Manually Data Loading'
,p_static_id=>'manually-data-loading'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_data BLOB;',
'    l_load_result apex_data_loading.t_data_load_result;',
'BEGIN',
'    SELECT blob_content',
'      INTO l_data',
'      FROM apex_application_temp_files',
'     WHERE name = :P3_FILE;',
'',
'INSERT INTO DEMO_DATA_LOAD(',
'            EMPLOYEE_NAME,',
'            DEPARTMENT,',
'            EMAIL,',
'            JOINING_DATE,',
'            DATE_OF_BIRTH,',
'            SALARY,',
'            BONUS,',
'            EXPERIENCE_YRS,',
'            STATUS',
'        )',
'        SELECT',
'            INITCAP(TRIM(col001)), --  EMPLOYEE_NAME',
'            UPPER(TRIM(col002)), --DEPARTMENT, ',
'            LOWER(TRIM(col003)) , -- EMAIL',
'            CASE',
'                WHEN TRIM(col004) IS NOT NULL',
'                THEN TO_DATE(TRIM(col004), ''YYYY-MM-DD'')',
'            END , -- JOINING_DATE',
'            CASE',
'                WHEN TRIM(col005) IS NOT NULL',
'                THEN TO_DATE(TRIM(col005), ''YYYY-MM-DD'')',
'            END , -- DATE_OF_BIRTH',
'            CASE',
'                WHEN TRIM(col006) IS NOT NULL',
'                THEN TO_NUMBER(TRIM(col006), ''999999999999D99'')',
'            END , -- SALARY',
'            CASE',
'                WHEN TRIM(col007) IS NOT NULL',
'                THEN TO_NUMBER(TRIM(col007), ''999999999999D99'')',
'            END , -- BONUS',
'            CASE',
'                WHEN TRIM(col008) IS NOT NULL',
'                THEN TO_NUMBER(TRIM(col008), ''999D99'')',
'            END , -- EXPERIENCE_YRS',
'            UPPER(TRIM(col009))  -- STATUS',
'        FROM TABLE(',
'            apex_data_parser.parse(',
'                p_content   => l_data,',
'                p_skip_rows => 1,',
'                p_file_type => apex_data_parser.c_file_type_xlsx',
'            )',
'        )',
'        WHERE NOT (',
'               col001 IS NULL',
'           AND col002 IS NULL',
'           AND col003 IS NULL',
'           AND col004 IS NULL',
'           AND col005 IS NULL',
'           AND col006 IS NULL',
'           AND col007 IS NULL',
'           AND col008 IS NULL',
'           AND col009 IS NULL',
'        );',
'',
'    :P3_ERROR_ROW_COUNT := 0;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(35790588252312789064)
,p_process_success_message=>'Data Loaded Successfully !'
,p_internal_uid=>33219523615752145532
,p_created_on=>wwv_flow_imp.dz('20260907095800Z')
,p_updated_on=>wwv_flow_imp.dz('20260907095800Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
end;
