wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(35824068150863087282)
,p_name=>'Preview'
,p_static_id=>'preview'
,p_template=>4073835273271169698
,p_display_sequence=>40
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--horizontalBorders:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'       (p.line_number - 1) AS SEQ,',
'       INITCAP(TRIM(p.col001)) AS EMPLOYEE_NAME,',
'       UPPER(TRIM(p.col002)) AS DEPARTMENT,',
'       LOWER(TRIM(p.col003)) AS EMAIL,',
'       TO_DATE(TRIM(p.col004), ''YYYY-MM-DD'') AS JOINING_DATE,',
'       TO_DATE(TRIM(p.col005), ''YYYY-MM-DD'') AS DATE_OF_BIRTH,',
'       TO_NUMBER(TRIM(p.col006), ''999999999999D99'') AS SALARY,',
'       TO_NUMBER(TRIM(p.col007), ''999999999999D99'') AS BONUS,',
'       TO_NUMBER(TRIM(p.col008), ''999D99'') AS EXPERIENCE_YRS,',
'       UPPER(TRIM(p.col009)) AS STATUS',
'FROM apex_application_temp_files f,',
'     TABLE(',
'         apex_data_parser.parse(',
'             p_content         => f.blob_content,',
'             p_file_name       => f.filename,',
'             p_xlsx_sheet_name =>',
'                 CASE',
'                     WHEN :P4_XLSX_WORKSHEET IS NOT NULL',
'                     THEN :P4_XLSX_WORKSHEET',
'                 END,',
'             p_file_profile    =>',
'                 apex_data_loading.get_file_profile(',
'                     p_static_id => ''employee-data-loading-using-collection''',
'                 ),',
'             p_max_rows        => 100',
'         )',
'     ) p',
'',
'WHERE f.name = :P4_FILE',
'  AND p.line_number <> 1;'))
,p_display_when_condition=>'P4_FILE'
,p_display_condition_type=>'ITEM_IS_NOT_NULL'
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'No data found.'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_created_on=>wwv_flow_imp.dz('20260907103324Z')
,p_updated_on=>wwv_flow_imp.dz('20260907105032Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
