wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(33219524974819145545)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insert Data Into Table Using Collection'
,p_static_id=>'insert-data-into-table-using-collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_collection_exists NUMBER := 0;',
'    l_record_count      NUMBER := 0;',
'BEGIN',
'',
'    /* Check if collection exists */',
'    SELECT COUNT(*)',
'      INTO l_collection_exists',
'      FROM APEX_COLLECTIONS',
'     WHERE COLLECTION_NAME = ''EMPLOYEE_DATA_LOADING'';',
'',
'    IF l_collection_exists = 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Employee data collection not found. Please upload the file again.''',
'        );',
'    END IF;',
'',
'',
'    /* Check if collection contains records */',
'    SELECT COUNT(*)',
'      INTO l_record_count',
'      FROM APEX_COLLECTIONS',
'     WHERE COLLECTION_NAME = ''EMPLOYEE_DATA_LOADING'';',
'',
'    IF l_record_count = 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20002,',
'            ''Employee data collection is empty. Nothing to import.''',
'        );',
'    END IF;',
'',
'',
'    /* Insert data */',
'    INSERT INTO DEMO_DATA_LOAD',
'    (',
'        EMPLOYEE_NAME,',
'        DEPARTMENT,',
'        EMAIL,',
'        JOINING_DATE,',
'        DATE_OF_BIRTH,',
'        SALARY,',
'        BONUS,',
'        EXPERIENCE_YRS,',
'        STATUS',
'    )',
'    SELECT',
'        INITCAP(TRIM(c001)) AS EMPLOYEE_NAME,',
'',
'        UPPER(TRIM(c002)) AS DEPARTMENT,',
'',
'        LOWER(TRIM(c003)) AS EMAIL,',
'',
'        CASE',
'            WHEN TRIM(c004) IS NOT NULL',
'            THEN TO_DATE(TRIM(c004), ''RRRR-MM-DD'')',
'        END AS JOINING_DATE,',
'',
'        CASE',
'            WHEN TRIM(c005) IS NOT NULL',
'            THEN TO_DATE(TRIM(c005), ''RRRR-MM-DD'')',
'        END AS DATE_OF_BIRTH,',
'',
'        CASE',
'            WHEN TRIM(c006) IS NOT NULL',
'            THEN TO_NUMBER(TRIM(c006))',
'        END AS SALARY,',
'',
'        CASE',
'            WHEN TRIM(c007) IS NOT NULL',
'            THEN TO_NUMBER(TRIM(c007))',
'        END AS BONUS,',
'',
'        CASE',
'            WHEN TRIM(c008) IS NOT NULL',
'            THEN TO_NUMBER(TRIM(c008))',
'        END AS EXPERIENCE_YRS,',
'',
'        UPPER(TRIM(c009)) AS STATUS',
'',
'    FROM APEX_COLLECTIONS',
'    WHERE COLLECTION_NAME = ''EMPLOYEE_DATA_LOADING''',
'      AND NOT',
'      (',
'             c001 IS NULL',
'         AND c002 IS NULL',
'         AND c003 IS NULL',
'         AND c004 IS NULL',
'         AND c005 IS NULL',
'         AND c006 IS NULL',
'         AND c007 IS NULL',
'         AND c008 IS NULL',
'         AND c009 IS NULL',
'      );',
'',
'',
'    /* Reset error count */',
'    :P4_ERROR_ROW_COUNT := 0;',
'',
'    COMMIT;',
'',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        ROLLBACK;',
'',
'        :P4_ERROR_ROW_COUNT := NVL(:P4_ERROR_ROW_COUNT, 0) + 1;',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20003,',
'            ''Error while importing employee data. '' || SQLERRM',
'        );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(35824061539643087275)
,p_internal_uid=>33219524974819145545
,p_created_on=>wwv_flow_imp.dz('20260907104647Z')
,p_updated_on=>wwv_flow_imp.dz('20260907104959Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
