'function colorBreakValues() {',
'  document.querySelectorAll(".a-GV-breakValue").forEach(el => {',
'    let txt = (el.innerText || "").trim().toLowerCase();',
' ',
'    el.classList.remove("valid", "invalid");',
' ',
'    // if text contains validated -> green',
'    if (txt.includes("validated")) {',
'      el.classList.add("valid");',
'    } else {',
'      // everything else -> red (invalid messages)',
'      el.classList.add("invalid");',
'    }',
'  });',
'}',
' ',
'/* First Run */',
'colorBreakValues();',
' ',
'/* Run after any refresh (IR/IG/Classic report) */',
'$(document).on("apexafterrefresh", function () {',
'  colorBreakValues();',
'});',
' ',
'/* Live changes observer */',
'const obs = new MutationObserver(() => colorBreakValues());',
'obs.observe(document.body, { childList: true, subtree: true });'))
