wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(33219525223062145548)
,p_plug_name=>'Preview IG'
,p_static_id=>'preview-ig'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>50
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'       (p.line_number - 1) AS SEQ,',
'',
'       INITCAP(TRIM(p.col001)) AS EMPLOYEE_NAME,',
'',
'       UPPER(TRIM(p.col002)) AS DEPARTMENT,',
'',
'       LOWER(TRIM(p.col003)) AS EMAIL,',
'',
'       TO_CHAR(',
'           COALESCE(',
'               TO_DATE(',
'                   TRIM(p.col004)',
'                   DEFAULT NULL ON CONVERSION ERROR,',
'                   ''YYYY-MM-DD''',
'               ),',
'               TO_DATE(',
'                   TRIM(p.col004)',
'                   DEFAULT NULL ON CONVERSION ERROR,',
'                   ''DD/MM/YYYY''',
'               ),',
'               TO_DATE(',
'                   TRIM(p.col004)',
'                   DEFAULT NULL ON CONVERSION ERROR,',
'                   ''DD-MON-YYYY''',
'               )',
'           ),',
'           ''DD-MON-YYYY''',
'       ) AS JOINING_DATE,',
'',
'       TO_CHAR(',
'           COALESCE(',
'               TO_DATE(',
'                   TRIM(p.col005)',
'                   DEFAULT NULL ON CONVERSION ERROR,',
'                   ''YYYY-MM-DD''',
'               ),',
'               TO_DATE(',
'                   TRIM(p.col005)',
'                   DEFAULT NULL ON CONVERSION ERROR,',
'                   ''DD/MM/YYYY''',
'               ),',
'               TO_DATE(',
'                   TRIM(p.col005)',
'                   DEFAULT NULL ON CONVERSION ERROR,',
'                   ''DD-MON-YYYY''',
'               )',
'           ),',
'           ''DD-MON-YYYY''',
'       ) AS DATE_OF_BIRTH,',
'',
'       TO_NUMBER(',
'           TRIM(p.col006)',
'           DEFAULT NULL ON CONVERSION ERROR',
'       ) AS SALARY,',
'',
'       TO_NUMBER(',
'           TRIM(p.col007)',
'           DEFAULT NULL ON CONVERSION ERROR',
'       ) AS BONUS,',
'',
'       TO_NUMBER(',
'           TRIM(p.col008)',
'           DEFAULT NULL ON CONVERSION ERROR',
'       ) AS EXPERIENCE_YRS,',
'',
'       UPPER(TRIM(p.col009)) AS STATUS,',
'',
'',
'       /* ================================================================',
'          1. VALIDATION STATUS',
'          ================================================================ */',
'',
'       CASE',
'           WHEN TRIM(p.col001) IS NOT NULL',
'            AND TRIM(p.col002) IS NOT NULL',
'            AND TRIM(p.col003) IS NOT NULL',
'            AND TRIM(p.col004) IS NOT NULL',
'            AND TRIM(p.col005) IS NOT NULL',
'            AND TRIM(p.col006) IS NOT NULL',
'            AND TRIM(p.col007) IS NOT NULL',
'            AND TRIM(p.col008) IS NOT NULL',
'            AND TRIM(p.col009) IS NOT NULL',
'',
'            AND pkg_data_validation.name(',
'                    p_name         => p.col001,',
'                    p_min_length   => 3,',
'                    p_field_label  => ''Employee Name''',
'                ) IS NULL',
'',
'            AND pkg_data_validation.department(',
'                    p_department => p.col002',
'                ) IS NULL',
'',
'            AND pkg_data_validation.email(',
'                    p_email => p.col003',
'                ) IS NULL',
'',
'            AND pkg_data_validation.salary(',
'                    p_salary => p.col006',
'                ) IS NULL',
'',
'            AND pkg_data_validation.bonus(',
'                    p_bonus => p.col007',
'                ) IS NULL',
'',
'            AND pkg_data_validation.experience_years(',
'                    p_experience => p.col008',
'                ) IS NULL',
'',
'            AND pkg_data_validation.future_date(',
'                    p_date        => p.col004,',
'                    p_field_label => ''Joining Date''',
'                ) IS NULL',
'',
'            AND pkg_data_validation.future_date(',
'                    p_date        => p.col005,',
'                    p_field_label => ''Date of Birth''',
'                ) IS NULL',
'',
'            AND pkg_data_validation.dob_before_joining(',
'                    p_dob          => p.col005,',
'                    p_joining_date => p.col004',
'                ) IS NULL',
'',
'            AND pkg_data_validation.status(',
'                    p_status => p.col009',
'                ) IS NULL',
'',
'           THEN ''Validated''',
'',
'           ELSE ''Invalid Data''',
'       END AS VALIDATION_STATUS,',
'',
'',
'       /* ================================================================',
'          2. ERROR MESSAGE',
'          ================================================================ */',
'',
'       RTRIM(',
'',
'           /* Required Fields */',
'',
'           CASE',
'               WHEN TRIM(p.col001) IS NULL',
'               THEN ''Employee Name is required, ''',
'               ELSE ''''',
'           END ||',
'',
'           CASE',
'               WHEN TRIM(p.col002) IS NULL',
'               THEN ''Department is required, ''',
'               ELSE ''''',
'           END ||',
'',
'           CASE',
'               WHEN TRIM(p.col003) IS NULL',
'               THEN ''Email is required, ''',
'               ELSE ''''',
'           END ||',
'',
'           CASE',
'               WHEN TRIM(p.col004) IS NULL',
'               THEN ''Joining Date is required, ''',
'               ELSE ''''',
'           END ||',
'',
'           CASE',
'               WHEN TRIM(p.col005) IS NULL',
'               THEN ''Date of Birth is required, ''',
'               ELSE ''''',
'           END ||',
'',
'           CASE',
'               WHEN TRIM(p.col006) IS NULL',
'               THEN ''Salary is required, ''',
'               ELSE ''''',
'           END ||',
'',
'           CASE',
'               WHEN TRIM(p.col007) IS NULL',
'               THEN ''Bonus is required, ''',
'               ELSE ''''',
'           END ||',
'',
'           CASE',
'               WHEN TRIM(p.col008) IS NULL',
'               THEN ''Experience Years is required, ''',
'               ELSE ''''',
'           END ||',
'',
'           CASE',
'               WHEN TRIM(p.col009) IS NULL',
'               THEN ''Status is required, ''',
'               ELSE ''''',
'           END ||',
'',
'',
'           /* Employee Name */',
'',
'           CASE',
'               WHEN TRIM(p.col001) IS NOT NULL',
'                AND pkg_data_validation.name(',
'                        p_name         => p.col001,',
'                        p_min_length   => 3,',
'                        p_field_label  => ''Employee Name''',
'                    ) IS NOT NULL',
'               THEN',
'                   pkg_data_validation.name(',
'                       p_name         => p.col001,',
'                       p_min_length   => 3,',
'                       p_field_label  => ''Employee Name''',
'                   ) || '', ''',
'               ELSE ''''',
'           END ||',
'',
'',
'           /* Department */',
'',
'           CASE',
'               WHEN TRIM(p.col002) IS NOT NULL',
'                AND pkg_data_validation.department(',
'                        p_department => p.col002',
'                    ) IS NOT NULL',
'               THEN',
'                   pkg_data_validation.department(',
'                       p_department => p.col002',
'                   ) || '', ''',
'               ELSE ''''',
'           END ||',
'',
'',
'           /* Email */',
'',
'           CASE',
'               WHEN TRIM(p.col003) IS NOT NULL',
'                AND pkg_data_validation.email(',
'                        p_email => p.col003',
'                    ) IS NOT NULL',
'               THEN',
'                   pkg_data_validation.email(',
'                       p_email => p.col003',
'                   ) || '', ''',
'               ELSE ''''',
'           END ||',
'',
'',
'           /* Salary */',
'',
'           CASE',
'               WHEN TRIM(p.col006) IS NOT NULL',
'                AND pkg_data_validation.salary(',
'                        p_salary => p.col006',
'                    ) IS NOT NULL',
'               THEN',
'                   pkg_data_validation.salary(',
'                       p_salary => p.col006',
'                   ) || '', ''',
'               ELSE ''''',
'           END ||',
'',
'',
'           /* Bonus */',
'',
'           CASE',
'               WHEN TRIM(p.col007) IS NOT NULL',
'                AND pkg_data_validation.bonus(',
'                        p_bonus => p.col007',
'                    ) IS NOT NULL',
'               THEN',
'                   pkg_data_validation.bonus(',
'                       p_bonus => p.col007',
'                   ) || '', ''',
'               ELSE ''''',
'           END ||',
'',
'',
'           /* Experience Years */',
'',
'           CASE',
'               WHEN TRIM(p.col008) IS NOT NULL',
'                AND pkg_data_validation.experience_years(',
'                        p_experience => p.col008',
'                    ) IS NOT NULL',
'               THEN',
'                   pkg_data_validation.experience_years(',
'                       p_experience => p.col008',
'                   ) || '', ''',
'               ELSE ''''',
'           END ||',
'',
'',
'           /* Joining Date */',
'',
'           CASE',
'               WHEN TRIM(p.col004) IS NOT NULL',
'                AND pkg_data_validation.future_date(',
'                        p_date        => p.col004,',
'                        p_field_label => ''Joining Date''',
'                    ) IS NOT NULL',
'               THEN',
'                   pkg_data_validation.future_date(',
'                       p_date        => p.col004,',
'                       p_field_label => ''Joining Date''',
'                   ) || '', ''',
'               ELSE ''''',
'           END ||',
'',
'',
'           /* Date of Birth */',
'',
'           CASE',
'               WHEN TRIM(p.col005) IS NOT NULL',
'                AND pkg_data_validation.future_date(',
'                        p_date        => p.col005,',
'                        p_field_label => ''Date of Birth''',
'                    ) IS NOT NULL',
'               THEN',
'                   pkg_data_validation.future_date(',
'                       p_date        => p.col005,',
'                       p_field_label => ''Date of Birth''',
'                   ) || '', ''',
'               ELSE ''''',
'           END ||',
'',
'',
'           /* DOB vs Joining Date */',
'',
'           CASE',
'               WHEN TRIM(p.col004) IS NOT NULL',
'                AND TRIM(p.col005) IS NOT NULL',
'                AND pkg_data_validation.dob_before_joining(',
'                        p_dob          => p.col005,',
'                        p_joining_date => p.col004',
'                    ) IS NOT NULL',
'               THEN',
'                   pkg_data_validation.dob_before_joining(',
'                       p_dob          => p.col005,',
'                       p_joining_date => p.col004',
'                   ) || '', ''',
'               ELSE ''''',
'           END ||',
'',
'',
'           /* Status */',
'',
'           CASE',
'               WHEN TRIM(p.col009) IS NOT NULL',
'                AND pkg_data_validation.status(',
'                        p_status => p.col009',
'                    ) IS NOT NULL',
'               THEN',
'                   pkg_data_validation.status(',
'                       p_status => p.col009',
'                   ) || '', ''',
'               ELSE ''''',
'           END,',
'',
'           '', ''',
'',
'       ) AS ERROR_MESSAGE',
'',
'',
'FROM apex_application_temp_files f,',
'',
'     TABLE(',
'         apex_data_parser.parse(',
'             p_content         => f.blob_content,',
'',
'             p_file_name       => f.filename,',
'',
'             p_xlsx_sheet_name =>',
'                 CASE',
'                     WHEN :P5_XLSX_WORKSHEET IS NOT NULL',
'                     THEN :P5_XLSX_WORKSHEET',
'                 END,',
'',
'             p_file_profile    =>',
'                 apex_data_loading.get_file_profile(',
'                     p_static_id => ''employee-data-loading''',
'                 ),',
'',
'             p_max_rows        => 100',
'         )',
'     ) p',
'',
'WHERE f.name = :P5_FILE',
'  AND p.line_number <> 1;'))
,p_plug_source_type=>'NATIVE_IG'
,p_plug_display_condition_type=>'ITEM_IS_NOT_NULL'
,p_plug_display_when_condition=>'P5_FILE'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
