wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(35844273894580989617)
,p_event_id=>wwv_flow_imp.id(35844273706390989616)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_static_id=>'native-set-value'
,p_action=>'NATIVE_SET_VALUE'
,p_affected_elements_type=>'ITEM'
,p_affected_elements=>'P5_INVALID_RECORD'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'escape_special_characters', 'Y',
  'items_to_submit', 'P5_FILE',
  'sql_query', wwv_flow_string.join(wwv_flow_t_varchar2(
    'SELECT COUNT(*) AS total_invalid_or_duplicate',
    'FROM (',
    '    SELECT',
    '        CASE',
    '            WHEN TRIM(p.col001) IS NOT NULL',
    '             AND TRIM(p.col002) IS NOT NULL',
    '             AND TRIM(p.col003) IS NOT NULL',
    '             AND TRIM(p.col004) IS NOT NULL',
    '             AND TRIM(p.col005) IS NOT NULL',
    '             AND TRIM(p.col006) IS NOT NULL',
    '             AND TRIM(p.col007) IS NOT NULL',
    '             AND TRIM(p.col008) IS NOT NULL',
    '             AND TRIM(p.col009) IS NOT NULL',
    '',
    '             /* Employee Name */',
    '             AND pkg_data_validation.name(',
    '                     p_name         => p.col001,',
    '                     p_min_length   => 3,',
    '                     p_field_label  => ''Employee Name''',
    '                 ) IS NULL',
    '',
    '             /* Department */',
    '             AND pkg_data_validation.department(',
    '                     p_department => p.col002',
    '                 ) IS NULL',
    '',
    '             /* Email */',
    '             AND pkg_data_validation.email(',
    '                     p_email => p.col003',
    '                 ) IS NULL',
    '',
    '             /* Joining Date */',
    '             AND pkg_data_validation.future_date(',
    '                     p_date        => p.col004,',
    '                     p_field_label => ''Joining Date''',
    '                 ) IS NULL',
    '',
    '             /* Date of Birth */',
    '             AND pkg_data_validation.future_date(',
    '                     p_date        => p.col005,',
    '                     p_field_label => ''Date of Birth''',
    '                 ) IS NULL',
    '',
    '             /* DOB must be before Joining Date */',
    '             AND pkg_data_validation.dob_before_joining(',
    '                     p_dob          => p.col005,',
    '                     p_joining_date => p.col004',
    '                 ) IS NULL',
    '',
    '             /* Salary */',
    '             AND pkg_data_validation.salary(',
    '                     p_salary => p.col006',
    '                 ) IS NULL',
    '',
    '             /* Bonus */',
    '             AND pkg_data_validation.bonus(',
    '                     p_bonus => p.col007',
    '                 ) IS NULL',
    '',
    '             /* Experience Years */',
    '             AND pkg_data_validation.experience_years(',
    '                     p_experience => p.col008',
    '                 ) IS NULL',
    '',
    '             /* Status */',
    '             AND pkg_data_validation.status(',
    '                     p_status => p.col009',
    '                 ) IS NULL',
    '',
    '            THEN ''Validated''',
    '            ELSE ''Invalid Data''',
    '        END AS VALIDATION_STATUS',
    '',
    '    FROM TABLE (',
    '        apex_data_parser.parse(',
    '            p_content =>',
    '                (',
    '                    SELECT blob_content',
    '                    FROM apex_application_temp_files',
    '                    WHERE name = :P5_FILE',
    '                ),',
    '',
    '            p_file_name =>',
    '                (',
    '                    SELECT filename',
    '                    FROM apex_application_temp_files',
    '                    WHERE name = :P5_FILE',
    '                ),',
    '',
    '            p_file_profile =>',
    '                apex_data_loading.get_file_profile(',
    '                    p_static_id => ''employee-data''',
    '                ),',
    '',
    '            p_max_rows => 100',
    '        )',
    '    ) p',
    '',
    '    WHERE p.line_number <> 1',
    '',
    '      AND (',
    '             TRIM(p.col001) IS NOT NULL',
    '          OR TRIM(p.col002) IS NOT NULL',
    '          OR TRIM(p.col003) IS NOT NULL',
    '          OR TRIM(p.col004) IS NOT NULL',
    '          OR TRIM(p.col005) IS NOT NULL',
    '          OR TRIM(p.col006) IS NOT NULL',
    '          OR TRIM(p.col007) IS NOT NULL',
    '          OR TRIM(p.col008) IS NOT NULL',
    '          OR TRIM(p.col009) IS NOT NULL',
    '      )',
    ') t',
    'WHERE t.validation_status = ''Invalid Data'';')),
  'suppress_change_event', 'N',
  'type', 'SQL_STATEMENT')).to_clob
,p_wait_for_result=>'Y'
,p_created_on=>wwv_flow_imp.dz('20260907111521Z')
,p_updated_on=>wwv_flow_imp.dz('20260907111521Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
